pub(crate) const STYLES: &str = r#"
.df-sheet{--gold:#dfbb77;--ink:#09111c;--muted:#aab8c6;position:relative;isolation:isolate;min-height:100svh;background:var(--ink);color:#eee8dc;font:15px/1.65 system-ui,sans-serif;overflow:hidden}.df-sheet *{box-sizing:border-box}.df-sheet [hidden]{display:none!important}.df-sheet .sheet-art{position:absolute;inset:0;width:100%;height:590px;object-fit:cover;object-position:50% 50%;z-index:-3}.df-sheet:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,#07101aa6,#07101a55 130px,#09111cf5 440px,#09111c 590px),linear-gradient(90deg,#07101ab8,transparent)}
.df-sheet .sheet-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:22px 5vw;border-bottom:1px solid #dfbb7730;background:#07101a75}.df-sheet .sheet-brand{color:#efd4a1;font:26px Georgia,serif;letter-spacing:-.8px}.df-sheet .sheet-connection{color:#b7c9d6;font-size:11px;letter-spacing:1px;margin:0}.df-sheet .sheet-hero{width:min(1180px,90vw);margin:0 auto;padding:66px 0 35px}.df-sheet .sheet-identity{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--gold);margin:0 0 12px}.df-sheet h1{font:clamp(46px,6vw,76px)/1.1 Georgia,serif;letter-spacing:-2px;margin:0 0 17px;text-shadow:0 3px 22px #0009}.df-sheet .sheet-subtitle{font:18px/1.7 Georgia,serif;color:#dddace;max-width:710px;margin:0}.df-sheet .sheet-art-fallback{color:var(--muted);font-size:12px}.df-sheet .sheet-notice{width:min(1180px,90vw);margin:0 auto 20px;padding:11px 17px;border:1px solid #bda36c4d;border-left:3px solid #d2af68;background:#101d2bd9;color:#e8d8b5;font-size:12px}
.df-sheet .sheet-workspace{width:min(1180px,90vw);margin:0 auto 70px;padding:26px 30px 35px;border:1px solid #dfbb7740;border-radius:5px;background:linear-gradient(130deg,#132131ed,#09111cf7);box-shadow:0 25px 60px #0005}.df-sheet .sheet-tabs{display:flex;gap:6px;border-bottom:1px solid #c5ad773b;padding:0 0 18px;overflow-x:auto}.df-sheet button{font:12px/1.4 system-ui,sans-serif;min-height:44px;border:1px solid #9ea9b044;border-radius:3px;padding:10px 18px;background:#101e2d;color:#cbd5dc;cursor:pointer;white-space:normal}.df-sheet .sheet-tabs button{flex:1;white-space:nowrap}.df-sheet button:hover,.df-sheet button[aria-selected=true]{border-color:#d4b371;color:#f6deb0;background:#795b2538}.df-sheet button:disabled{opacity:.55;cursor:default}.df-sheet button:focus-visible,.df-sheet input:focus-visible,.df-sheet summary:focus-visible,.df-sheet .sheet-tab-panel:focus-visible{outline:2px solid #9bd6f4;outline-offset:4px}.df-sheet .sheet-filter{display:grid;gap:7px;margin:22px 0 30px;font-size:12px;color:#bac6d1;max-width:410px}.df-sheet .sheet-filter input{font:14px system-ui,sans-serif;color:#eee8dc;background:#081321;border:1px solid #8194a650;border-radius:3px;padding:11px 13px;min-height:44px;width:100%}.df-sheet .sheet-filter p{margin:0}
.df-sheet .sheet-tab-panel{display:grid;gap:32px}.df-sheet h2{font:25px/1.3 Georgia,serif;color:#f0dcba;margin:0 0 5px}.df-sheet .sheet-caption{font-size:12px;color:var(--muted);margin:0 0 16px}.df-sheet .sheet-rows{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;align-items:start}.df-sheet .sheet-row{border:1px solid #98a9ba32;background:#091421ad;border-radius:3px;min-width:0}.df-sheet .sheet-row[open]{border-color:#b89c6066;background:#111e2c}.df-sheet .sheet-row-heading{padding:17px 18px;min-height:58px;cursor:pointer;position:relative;display:flex;align-items:center;gap:15px;list-style:none}.df-sheet .sheet-row-heading::-webkit-details-marker{display:none}.df-sheet .sheet-row-heading:before{content:'+';font-size:19px;color:#b69b65;flex:0 0 14px}.df-sheet .sheet-row[open] .sheet-row-heading:before{content:'−'}.df-sheet .sheet-row-title{font:17px/1.4 Georgia,serif;flex:1;overflow-wrap:anywhere}.df-sheet .sheet-row-value{font-size:12px;line-height:1.5;color:#d6ba84;text-align:right;max-width:47%;overflow-wrap:anywhere}.df-sheet .sheet-row-body{padding:0 18px 20px 47px}.df-sheet .sheet-row-summary{margin:0 0 15px;color:#bcc8d1;font-size:13px;overflow-wrap:anywhere}.df-sheet .sheet-fields{display:grid;grid-template-columns:minmax(80px,.8fr) minmax(0,1.2fr);gap:8px 15px;font-size:12px;margin:0}.df-sheet dt{color:#91a5b6}.df-sheet dd{color:#e1ddd3;margin:0;overflow-wrap:anywhere}.df-sheet .sheet-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:17px}.df-sheet .sheet-actions:empty{display:none}.df-sheet .sheet-actions button{color:#efd6a2;border-color:#b393575c;font-size:12px}.df-sheet .sheet-empty{color:var(--muted);text-align:center;padding:35px;border:1px dashed #b69b653d}
@media(max-width:700px){.df-sheet .sheet-header{padding:18px 5vw;align-items:start}.df-sheet .sheet-brand{font-size:23px}.df-sheet .sheet-connection{max-width:140px;text-align:right}.df-sheet .sheet-hero{padding:53px 0 29px}.df-sheet .sheet-subtitle{font-size:16px}.df-sheet .sheet-workspace{padding:19px 16px 25px;width:94vw}.df-sheet .sheet-tabs{gap:4px}.df-sheet .sheet-tabs button{padding:10px 12px;flex:0 0 auto;font-size:12px}.df-sheet .sheet-rows{grid-template-columns:1fr}.df-sheet .sheet-filter{max-width:none;margin:20px 0 24px}.df-sheet .sheet-row-heading{padding:15px 13px;gap:10px}.df-sheet .sheet-row-body{padding:0 15px 20px 37px}.df-sheet .sheet-fields{grid-template-columns:minmax(72px,.8fr) minmax(0,1.2fr);gap:9px 12px}.df-sheet .sheet-art{height:490px}.df-sheet .sheet-row-title{font-size:16px}.df-sheet .sheet-row-value{font-size:11px}}
@media(prefers-reduced-motion:reduce){.df-sheet *{scroll-behavior:auto}}
"#;
